examples.template:
HStack(spacing: theme.spacing.space1) {
    Text({{prefix}})
    Button({{user.name}}) { isShown = true }
        .buttonStyle(.monarchLink(.inline))
        .accessibilityHint("Shows a profile preview")
        .popover(isPresented: $isShown, arrowEdge: .top) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                HStack(spacing: theme.spacing.space3) {
                    MonarchAvatar(image: nil, name: {{user.name}}, seed: {{user.id}}, size: .lg, status: {{user.status|case}})
                    VStack(alignment: .leading, spacing: theme.spacing.space0_5) {
                        Text({{user.name}})
                            .monarchTextStyle(.subheading)
                            .accessibilityAddTraits(.isHeader)
                        Text({{user.handle}}).monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
                        Text({{user.title}}).monarchTextStyle(.bodySmall)
                        Text({{user.statusText}}).monarchTextStyle(.bodySmall).foregroundStyle(theme.colors.textMuted)
                    }
                }
                MonarchDivider()
                HStack(spacing: theme.spacing.space2) {
                    MonarchButton({{message}}, variant: .primary, size: .sm) { isShown = false }
                    MonarchButton({{profile}}, variant: .ghost, size: .sm) { isShown = false }
                }
            }
            .foregroundStyle(theme.colors.textDefault)
            .padding(theme.spacing.space4)
            .accessibilityElement(children: .contain)
            .accessibilityLabel("Profile of {{user.name|raw}}")
            .presentationCompactAdaptation(.popover)
            .presentationBackground(theme.colors.bgRaised)
        }
}

